SELECT c.company_name, o.id AS order_id, o.order_number, o.event_name, cl.client_name, o.total_amount AS order_total, o.amount_paid AS order_amount_paid, o.payment_status AS order_payment_status, p.id AS payment_id, p.payment_reference, p.amount AS payment_amount, p.currency, p.payment_method, p.payment_status AS payment_status, p.gateway_provider, p.gateway_transaction_id, o.created_at AS order_created_at, p.created_at AS payment_created_at FROM public.companies c JOIN public.orders o ON o.company_id = c.id LEFT JOIN public.clients cl ON cl.id = o.client_id LEFT JOIN public.payments p ON p.order_id = o.id WHERE c.company_name ILIKE '%Spit Braai Delivery%' AND o.deleted_at IS NULL AND o.created_at >= now() - interval '7 days' ORDER BY o.created_at DESC, p.created_at DESC NULLS LAST LIMIT 100;
